\title[The Septic Frontier]{The Septic Frontier: Conductor Information for\\ Affine Galois Groups in Prime Degree}
\author{Aristotle (Harmonic)}
\date{September 2026}

\begin{document}

\begin{abstract}
We study how much information a prime's residue class carries about the splitting type of a polynomial modulo that prime. The splitting field of $x^7-3$ has Galois group the Frobenius group $F_{42}=\AGL(1,7)$. Under Chebotarev equidistribution the question becomes an exact finite problem about the cycle types of the $42$ affine permutations $x\mapsto ax+b$ of $\Z/7$. We prove that the mutual information between the splitting type $T$ and the residue $p \bmod 7$ equals $\tfrac13+\lb 3$ bits. This is exactly the entropy of the order of a uniformly random element of the cyclic group $C_6$, the invariant that governs cyclic sextic fields. The total type entropy is $\tfrac{4}{21}+\tfrac67\lb 3+\tfrac16\lb 7$, so the residue mod $7$ explains about $95.1\%$ of it. We then prove the same law for every prime degree $q$: for $\AGL(1,q)$,
\[
I(T;\,p \bmod q)=\TT(q-1),\qquad H(T\mid p\bmod q)=\frac{q\lb q-(q-1)\lb(q-1)}{q(q-1)}\le\frac{\lb q}{q-1},
\]
where $\TT(n)$ is the cyclic type entropy of $C_n$. For odd $q$ the signal is at least one bit, and the explained fraction is at least $1-\lb q/(q-1)$. Two further results explain why the signal is confined to multiples of $7$. First, residues coprime to the conductor carry zero information in the linearly disjoint (product) model. Second, every homomorphism from an affine group to an abelian group kills all translations, so cyclotomic data sees only the linear part of the Frobenius. In particular the ramified prime $3$ is not a signal modulus. We confirm the predictions numerically by factoring $x^7-3$ modulo the $17{,}982$ unramified primes below $2\cdot10^5$.
\end{abstract}

\maketitle

\section{Introduction}

Let $f\in\Z[x]$ be irreducible of degree $n$, with splitting field $L$ and Galois group $G$ acting on the $n$ roots. For a prime $p$ unramified in $L$, the multiset of degrees of the irreducible factors of $f\bmod p$ is the \emph{splitting type} of $f$ at $p$. By a classical theorem of Frobenius and Dedekind, it equals the cycle type of the Frobenius element $\mathrm{Frob}_p\in G$. Chebotarev's density theorem says that $\mathrm{Frob}_p$ is equidistributed in $G$. So the statistics of splitting types are the statistics of cycle types of a uniformly random element of $G$.

We ask: \emph{how many bits of information about the splitting type are carried by the residue $p\bmod m$?} Writing $T$ for the splitting type and $R_m$ for the residue, both viewed as random variables in the Chebotarev model, we study the mutual information $I(T;R_m)$.

For fields with cyclic Galois group $C_n$ the splitting type is the order of the Frobenius, and the whole type entropy, which we call the \emph{cyclic type entropy} $\TT(n)$, is explained at the conductor. For $n=6$ it equals $\tfrac13+\lb 3$. This paper treats the first genuinely non-abelian step in prime degree, $x^7-3$, whose Galois group is $F_{42}=\AGL(1,7)$. Our main findings are:
\begin{enumerate}
\item \textbf{The framework extends.} The residue $p\bmod 7$ carries exactly $\TT(6)=\tfrac13+\lb 3\approx1.918$ bits about the septic splitting type.
\item \textbf{Every prime degree.} For $\AGL(1,q)$ the conductor information is exactly $\TT(q-1)$, and the residual has an explicit closed form. The residual is at most $\lb q/(q-1)$ and in fact tends to $0$ like $(\lb q)/q^2$.
\item \textbf{Where the signal lives.} Only multiples of the abelian conductor $7$ carry signal. Coprime moduli are flat, and abelian characters are blind to translations, so the ramified prime $3$ carries nothing.
\end{enumerate}

\subsection*{What is proved and what is assumed}
Sections~\ref{sec:entropy}--\ref{sec:where} contain exact statements about finite groups and entropies of uniform distributions, with complete proofs. The link to primes rests on two classical inputs:
\begin{itemize}
\item[(G)] the Galois group of $x^7-3$ is $F_{42}$, acting on the roots $\zeta_7^j\sqrt[7]{3}$ by $j\mapsto aj+b$, and the linear part $a$ of $\mathrm{Frob}_p$ is $p\bmod 7$;
\item[(C)] the Chebotarev density theorem.
\end{itemize}
The flatness statement at coprime moduli (Theorem~\ref{thm:flat}) is proved in the product model $F_{42}\times(\Z/m)^\times$. That model is the Chebotarev model of the compositum $L\cdot\Q(\zeta_m)$ when the two fields are linearly disjoint; we do not derive the disjointness from field theory here.

\section{Counting entropy on finite sample spaces}\label{sec:entropy}

\begin{definition}[Counting entropy]
Let $S$ be a non-empty finite set and $g:S\to B$. For $x\in S$ let $[x]_g=\{y\in S:g(y)=g(x)\}$. Define
\[
H_S(g)=\frac1{|S|}\sum_{x\in S}\lb\frac{|S|}{|[x]_g|}=-\sum_{v\in g(S)}\frac{|g^{-1}(v)|}{|S|}\lb\frac{|g^{-1}(v)|}{|S|}.
\]
\end{definition}

\begin{definition}[Conditional entropy, mutual information]
For $g:S\to B$ and $k:S\to C$, let $S_c=k^{-1}(c)$. Define
\[
H_S(g\mid k)=\sum_{c\in k(S)}\frac{|S_c|}{|S|}H_{S_c}(g),\qquad I_S(g;k)=H_S(g)-H_S(g\mid k).
\]
\end{definition}

\begin{definition}[Cyclic type entropy]
For $n\ge1$ and $i\in\Z/n$, let $\ord_n(i)=n/\gcd(i,n)$. Set $\TT(n)=H_{\Z/n}(\ord_n)$. Equivalently,
\[
\TT(n)=\sum_{d\mid n}\frac{\varphi(d)}{n}\lb\frac{n}{\varphi(d)}.
\]
For example $\TT(2)=1$, $\TT(4)=\tfrac32$, and $\TT(6)=\tfrac16\lb6+\tfrac16\lb6+\tfrac26\lb3+\tfrac26\lb3=\tfrac13+\lb3$.
\end{definition}

\begin{theorem}[Chain rule]\label{thm:chain}
For all $g,k$ on $S$, $H_S(g\mid k)=H_S(g,k)-H_S(k)$. Consequently
\[
I_S(g;k)=H_S(g)+H_S(k)-H_S(g,k)\quad\text{and}\quad I_S(g;k)=I_S(k;g).
\]
\end{theorem}

\begin{proof}[Proof sketch]
For $x\in S_c$, the $g$-fibre of $x$ inside $S_c$ is the $(g,k)$-fibre of $x$ in $S$. Hence
\[
\frac{|S_c|}{|S|}H_{S_c}(g)=\frac{|S_c|\lb|S_c|}{|S|}-\frac1{|S|}\sum_{x\in S_c}\lb|[x]_{(g,k)}|.
\]
Summing over $c$ and using $H_S(h)=\lb|S|-\frac1{|S|}\sum_x\lb|[x]_h|$ gives the chain rule. Symmetry holds because swapping coordinates does not change fibres.
\end{proof}

We also use three standard facts. Entropy is non-negative, so $0\le I\le H$. Coarse-graining never increases entropy: $H_S(\psi\circ g)\le H_S(g)$. Functions of different coordinates of a uniform product have zero mutual information.

\section{Cycle structure of affine maps over a field}\label{sec:affine}

Let $K$ be a field and $f_{a,b}(x)=ax+b$.

\begin{lemma}\label{lem:conj}
If $ax_0+b=x_0$, then $f_{a,b}^{\,k}(x)-x_0=a^k(x-x_0)$ for all $k\ge0$. If $a=1$, then $f_{1,b}^{\,k}(x)=x+kb$.
\end{lemma}
\begin{proof}
Induction on $k$.
\end{proof}

\begin{theorem}[Affine dynamics]\label{thm:affine}
Let $a\ne1$. Then $f_{a,b}$ has exactly one fixed point $x_0=b/(1-a)$. A point $x\ne x_0$ satisfies $f_{a,b}^{\,k}(x)=x$ iff $a^k=1$, and every $x\ne x_0$ has exact period $\ord(a)$. If $a=1$, $b\ne0$ and $\operatorname{char}K=q>0$, then $f_{1,b}$ has no fixed points and every point has exact period $q$.
\end{theorem}
\begin{proof}[Proof sketch]
By Lemma~\ref{lem:conj}, $f^k(x)-x=(a^k-1)(x-x_0)$ with $x-x_0\ne0$. The set of periods of $x$ is therefore the set of multiples of $\ord(a)$, so the minimal period is $\ord(a)$. For translations, $x+kb=x$ iff $q\mid k$.
\end{proof}

\begin{definition}[Affine type label]
For $(a,b)\in\AGL(1,q)$ let
\[
T(a,b)=\begin{cases}(q,1)&a=1,\ b=0,\\(0,q)&a=1,\ b\ne0,\\(1,\ord(a))&a\ne1.\end{cases}
\]
\end{definition}

\begin{corollary}[Faithfulness]
For every $(a,b)\in\AGL(1,q)$, the first coordinate of $T(a,b)$ is the number of fixed points of $f_{a,b}$ on $\Z/q$, and the second is the common length of all non-trivial cycles. Thus $T$ encodes exactly the cycle type.
\end{corollary}

\section{The septic model: \texorpdfstring{$x^7-3$}{x\^{}7-3} and \texorpdfstring{$F_{42}$}{F42}}\label{sec:septic}

Let $\alpha=\sqrt[7]3$ and $\zeta=\zeta_7$. The automorphisms $\sigma_{a,b}:\zeta\mapsto\zeta^a,\ \alpha\mapsto\zeta^b\alpha$ send $\zeta^j\alpha$ to $\zeta^{aj+b}\alpha$, and $\mathrm{Frob}_p=\sigma_{a,b}$ with $a\equiv p\pmod 7$. Put $S=F_{42}$, $T$ the type label with $q=7$, and $R(a,b)=a$. The orders in $(\Z/7)^\times$ are $\ord(1)=1$, $\ord(6)=2$, $\ord(2)=\ord(4)=3$ and $\ord(3)=\ord(5)=6$.

