\begin{theorem}[Septic type entropy]
$H(T)=\tfrac4{21}+\tfrac67\lb3+\tfrac16\lb7\approx2.01691$.
\end{theorem}
\begin{proof}
The fibre sizes are $1,6,7,14,14$ out of $42$. Expand $\lb42=1+\lb3+\lb7$ and $\lb6=1+\lb3$ and collect terms.
\end{proof}

\begin{theorem}[Massive signal at the conductor]\label{thm:septic}
$I(T;\,p\bmod7)=\tfrac13+\lb3\approx1.91830$.
\end{theorem}
\begin{proof}
$H(R)=\lb6$. The joint label has fibre sizes $1,6,7,7,7,7,7$, so $H(T,R)=\tfrac67+\tfrac67\lb3+\tfrac16\lb7$. By Theorem~\ref{thm:chain}, $I=\tfrac4{21}-\tfrac67+1+\lb3=\tfrac13+\lb3$.
\end{proof}

\begin{corollary}[The framework extends]
$I(T_{x^7-3};\,p\bmod7)=\TT(6)$.
\end{corollary}

\begin{corollary}[Residual and dominance]
$H(T\mid p\bmod7)=\dfrac{7\lb7-6\lb6}{42}\approx0.09861$ and $\tfrac{11}6<I(T;\,p\bmod7)\le H(T)$. The explained fraction is $I/H\approx95.11\%$.
\end{corollary}

\section{The conductor law in every prime degree}\label{sec:general}

Let $q$ be prime, $S_q=\AGL(1,q)$, $T$ the affine type label and $R(a,b)=a$.

\begin{lemma}[Entropy gaps under identical splittings]\label{lem:split}
Let $g,g',h,h'$ be functions on $S$ and $P\subseteq S$. Suppose $|[x]_g|=|[x]_{g'}|$ and $|[x]_h|=|[x]_{h'}|$ for $x\notin P$, and $|[x]_g|=|[x]_h|$ and $|[x]_{g'}|=|[x]_{h'}|$ for $x\in P$. Then $H_S(g)-H_S(h)=H_S(g')-H_S(h')$.
\end{lemma}
\begin{proof}
Split each fibre-log sum over $P$ and its complement and match terms.
\end{proof}

\begin{theorem}[Conductor law]\label{thm:conductor}
For every prime $q$, $I_{S_q}(T;R)=H_{S_q}(\ord\circ R)=\TT(q-1)$.
\end{theorem}
\begin{proof}[Proof sketch]
Apply Lemma~\ref{lem:split} with $g=T$, $h=(T,R)$, $g'=\ord\circ R$, $h'=R$ and $P=\{a=1\}$. Off $P$, $T$ and $\ord\circ R$ determine each other, and $(T,R)$ and $R$ determine each other. On $P$, $T$ forces $a=1$, and $\ord(a)=1$ iff $a=1$. Hence $H(T)-H(T,R)=H(\ord\circ R)-H(R)$, and so $I(T;R)=H(\ord\circ R)$. Since $\ord\circ R$ depends only on $a$, and $i\mapsto\gamma^i$ for a primitive root $\gamma$ is a bijection $\{0,\dots,q-2\}\to(\Z/q)^\times$ with $\ord(\gamma^i)=\ord_{q-1}(i)$, we get $H(\ord\circ R)=\TT(q-1)$.
\end{proof}

