\section{The universal residual}

\begin{theorem}[Residual law]\label{thm:residual}
$H_{S_q}(T\mid R)=\dfrac{q\lb q-(q-1)\lb(q-1)}{q(q-1)}$.
\end{theorem}
\begin{proof}[Proof sketch]
For $a\ne1$, $T$ is constant on the fibre. The fibre $a=1$ has weight $\tfrac1{q-1}$, and on it $T$ is a coin with probabilities $\tfrac1q,\tfrac{q-1}q$, whose entropy is $\lb q-\tfrac{q-1}q\lb(q-1)$.
\end{proof}

\begin{corollary}
$H_{S_q}(T)=\TT(q-1)+\dfrac{q\lb q-(q-1)\lb(q-1)}{q(q-1)}$, and $H_{S_q}(T\mid R)\le\dfrac{\lb q}{q-1}$.
\end{corollary}

\section{A one-bit floor and information completeness}

\begin{theorem}\label{thm:onebit}
For every $m\ge1$, $\TT(2m)\ge1$.
\end{theorem}
\begin{proof}[Proof sketch]
$\ord_{2m}(i)\mid m$ iff $i$ is even. So the coarse-graining $d\mapsto[d\mid m]$ of the order is the parity of $i$, a fair coin with entropy $1$. Coarse-graining does not increase entropy.
\end{proof}

\begin{corollary}
For every odd prime $q$, $I_{S_q}(T;R)\ge1$.
\end{corollary}

\begin{theorem}[Information completeness]
For every odd prime $q$,
\[
1-\frac{\lb q}{q-1}\le\frac{I_{S_q}(T;R)}{H_{S_q}(T)}.
\]
\end{theorem}
\begin{proof}
$I/H=1-\rho/H$ with $\rho=H(T\mid R)\le\lb q/(q-1)$ and $H\ge I\ge1$.
\end{proof}

\begin{remark}
The residual is much smaller than this bound. Since $(1+\tfrac1{q-1})^{q-1}<e$, we have $q\lb q-(q-1)\lb(q-1)<\lb q+\lb e$, so $\rho<(\lb q+\lb e)/(q(q-1))$.
\end{remark}

\section{Where the signal lives}\label{sec:where}

\begin{theorem}[Flat at coprime moduli]\label{thm:flat}
For any prime $q$ and finite set $C$, on the uniform product $S_q\times C$, $I(T\circ\pi_1;\pi_2)=0$. In particular, in the model $F_{42}\times(\Z/m)^\times$, the residue $p\bmod m$ carries no information about the septic type.
\end{theorem}
\begin{proof}
Functions of different coordinates of a uniform product are independent; apply Theorem~\ref{thm:chain}.
\end{proof}

Let $t_c(x)=x+c$, $s_a(x)=ax$ ($a\ne0$) and $[u,v]=uvu^{-1}v^{-1}$.

\begin{lemma}\label{lem:comm}
$t_{(a-1)c}=[s_a,t_c]$.
\end{lemma}
\begin{proof}
$s_at_cs_a^{-1}=t_{ac}$, so $[s_a,t_c]=t_{ac}t_{-c}=t_{(a-1)c}$.
\end{proof}

\begin{theorem}[Abelian characters kill translations]\label{thm:abelian}
Let $H$ be a group of permutations of a field $K$ that contains all translations and some scaling $s_a$ with $a\ne0,1$. Every homomorphism $\chi:H\to A$ into an abelian group satisfies $\chi(t_b)=1$ for all $b\in K$.
\end{theorem}
\begin{proof}
$t_b=[s_a,t_{b/(a-1)}]$ is a commutator, and $\chi$ kills commutators.
\end{proof}

\begin{remark}
The residue $p\bmod m$ is the Frobenius in the abelian group $\mathrm{Gal}(\Q(\zeta_m)/\Q)$. By Theorem~\ref{thm:abelian}, its restriction to $L\cap\Q(\zeta_m)$ factors through the linear part $a=p\bmod7$. Since $[F_{42},F_{42}]=C_7$ and $F_{42}^{\mathrm{ab}}\cong C_6$, the maximal abelian subfield of $L$ is $\Q(\zeta_7)$. The signal moduli are the multiples of the abelian conductor $7$. The ramified prime $3$ is not a signal modulus.
\end{remark}

