\section{Algorithms}

\begin{algorithm}[Exact affine channel]
Enumerate $S_q$; compute $T(a,b)$ with $\ord(a)$ cached per $a$; tabulate the fibres of $T$, $R$, $(T,R)$; return $H(T)$, $I=H(T)+H(R)-H(T,R)$ and $H(T\mid R)$. The cost is $O(q^2)$. Theorems~\ref{thm:conductor} and~\ref{thm:residual} reduce this to evaluating $\TT(q-1)$ over the divisors of $q-1$.
\end{algorithm}

\begin{algorithm}[Empirical splitting-type channel]
For each unramified prime $p<X$, compute the factor degrees of $f\bmod p$ from $\gcd(x^{p^d}-x,f)$, $d=1,2,\dots$; map them to a type label; compute the plug-in mutual information of $(T_p,\,p\bmod m)$ for each modulus $m$.
\end{algorithm}

\section{Discussion}

The residue channel of $\AGL(1,q)$ is informationally identical to the cyclic type channel of its abelianization $C_{q-1}$. Off the identity fibre of the linear part the type is the order of $a$, and on that fibre the type and the linear part split the mass identically, so the correction cancels. Residue data is abelian, so it sees only $G^{\mathrm{ab}}$. The relevant modulus is therefore the abelian conductor rather than an arbitrary ramified prime. The inputs (G) and (C) are classical but used rather than re-derived, and flatness is proved in the product model.

\section{Future directions}

\begin{conjecture}[Abelianization law]
For a Galois group $G\le S_n$ with type map $T$, in the Chebotarev model $\sup_m I(T;\,p\bmod m)=I(T;\,\mathrm{ab})$, where $\mathrm{ab}:G\to G^{\mathrm{ab}}$. In particular the signal vanishes at every modulus for perfect $G$, for example $\mathrm{PSL}(2,7)$ for $x^7-7x+3$.
\end{conjecture}

\begin{conjecture}[Sub-Frobenius groups]
For $d\mid q-1$ and $G_d=\{x\mapsto ax+b:a^d=1\}$, $I(T;a)=\TT(d)$ with residual $\dfrac{q\lb q-(q-1)\lb(q-1)}{q\,d}$.
\end{conjecture}

Further problems are to determine the sharp asymptotics of $1-I/H$, and to derive coprime flatness directly from linear disjointness of $L$ and $\Q(\zeta_m)$, treating non-disjoint moduli in full.

\section{Conclusion}

For $x^7-3$, knowing $p\bmod7$ determines the splitting type up to a single biased coin, and it carries exactly $\tfrac13+\lb3$ bits, the cyclic type entropy of degree six. In every prime degree the conductor signal of $\AGL(1,q)$ equals $\TT(q-1)$, the residual is explicit and at most $\lb q/(q-1)$, and abelian data is blind to translations. The type-channel framework extends beyond degree six.

