"""Exact conductor channel of AGL(1,q): brute force versus closed forms."""
from __future__ import annotations

import math
from collections import Counter
from typing import Dict, Hashable, Iterable, Tuple


def entropy(labels: Iterable[Hashable]) -> float:
    c = Counter(labels)
    n = sum(c.values())
    return -sum(k / n * math.log2(k / n) for k in c.values())


def mult_order(a: int, q: int) -> int:
    k, x = 1, a % q
    while x != 1:
        x, k = x * a % q, k + 1
    return k


def euler_phi(n: int) -> int:
    return sum(1 for k in range(1, n + 1) if math.gcd(k, n) == 1)


def cyclic_type_entropy(n: int) -> float:
    """T(n) = sum_{d | n} phi(d)/n * log2(n/phi(d))."""
    return sum(euler_phi(d) / n * math.log2(n / euler_phi(d)) for d in range(1, n + 1) if n % d == 0)


def affine_type(a: int, b: int, q: int) -> Tuple[int, int]:
    if a == 1:
        return (q, 1) if b == 0 else (0, q)
    return (1, mult_order(a, q))


def brute_force_channel(q: int) -> Dict[str, float]:
    orders = {a: mult_order(a, q) for a in range(1, q)}
    labels = [((q, 1) if (a == 1 and b == 0) else (0, q) if a == 1 else (1, orders[a]), a)
              for a in range(1, q) for b in range(q)]
    h_t = entropy(t for t, _ in labels)
    h_r = entropy(r for _, r in labels)
    h_tr = entropy(labels)
    info = h_t + h_r - h_tr
    return {"H(T)": h_t, "I": info, "residual": h_t - info}


def closed_form_channel(q: int) -> Dict[str, float]:
    info = cyclic_type_entropy(q - 1)
    res = (q * math.log2(q) - (q - 1) * math.log2(q - 1)) / (q * (q - 1))
    return {"H(T)": info + res, "I": info, "residual": res}


if __name__ == "__main__":
    for q in [3, 5, 7, 11, 13, 17, 19, 23]:
        bf, cf = brute_force_channel(q), closed_form_channel(q)
        assert all(abs(bf[k] - cf[k]) < 1e-9 for k in bf)
        print(f"q={q:>2}  I={cf['I']:.5f}  residual={cf['residual']:.5f}  H={cf['H(T)']:.5f}  "
              f"I/H={cf['I']/cf['H(T)']:.4f} >= {1 - math.log2(q)/(q-1):.4f}")

"""Empirical splitting-type channel via distinct-degree factorisation over F_p."""
from __future__ import annotations

import math
from collections import Counter
from typing import Dict, Hashable, Iterable, List, Sequence, Tuple

Poly = List[int]  # lowest degree first


def trim(f: Poly) -> Poly:
    while f and f[-1] == 0:
        f.pop()
    return f


def pmod(f: Poly, g: Poly, p: int) -> Poly:
    f = f[:]
    inv = pow(g[-1], p - 2, p)
    while len(f) >= len(g):
        c, s = f[-1] * inv % p, len(f) - len(g)
        for i, gi in enumerate(g):
            f[s + i] = (f[s + i] - c * gi) % p
        trim(f)
    return f


def pmulmod(f: Poly, g: Poly, m: Poly, p: int) -> Poly:
    if not f or not g:
        return []
    o = [0] * (len(f) + len(g) - 1)
    for i, a in enumerate(f):
        for j, b in enumerate(g):
            o[i + j] = (o[i + j] + a * b) % p
    return pmod(trim(o), m, p)


def ppowmod(f: Poly, e: int, m: Poly, p: int) -> Poly:
    r, b = [1], pmod(f, m, p)
    while e:
        if e & 1:
            r = pmulmod(r, b, m, p)
        b = pmulmod(b, b, m, p)
        e >>= 1
    return r


def pgcd(f: Poly, g: Poly, p: int) -> Poly:
    f, g = trim(f[:]), trim(g[:])
    while g:
        f, g = g, pmod(f, g, p)
    inv = pow(f[-1], p - 2, p)
    return [c * inv % p for c in f]


def pdivexact(f: Poly, g: Poly, p: int) -> Poly:
    f = f[:]
    q = [0] * (len(f) - len(g) + 1)
    inv = pow(g[-1], p - 2, p)
    while len(f) >= len(g) and f:
        c, s = f[-1] * inv % p, len(f) - len(g)
        q[s] = c
        for i, gi in enumerate(g):
            f[s + i] = (f[s + i] - c * gi) % p
        trim(f)
    return q


def factor_degrees(f: Poly, p: int) -> Tuple[int, ...]:
    """Distinct-degree factorisation of a squarefree monic f over F_p."""
    out: List[int] = []
    h: Poly = [0, 1]
    d = 0
    while len(f) - 1 >= 2 * (d + 1):
        d += 1
        h = ppowmod(h, p, f, p)                       # x^(p^d) mod f
        xh = trim([((h[i] if i < len(h) else 0) - (1 if i == 1 else 0)) % p
                   for i in range(max(len(h), 2))])
        g = pgcd(f, xh, p)                            # product of degree-d factors
        if len(g) > 1:
            out += [d] * ((len(g) - 1) // d)
            f = pdivexact(f, g, p)
            h = pmod(h, f, p)
    if len(f) > 1:
        out.append(len(f) - 1)
    return tuple(sorted(out))


def entropy(xs: Iterable[Hashable]) -> float:
    c = Counter(xs)
    n = sum(c.values())
    return -sum(k / n * math.log2(k / n) for k in c.values())


def mutual_information(pairs: Sequence[Tuple[Hashable, Hashable]]) -> float:
    return entropy(x for x, _ in pairs) + entropy(y for _, y in pairs) - entropy(pairs)


def splitting_channel(coeffs: Poly, bound: int, moduli: Sequence[int],
                      ramified: Sequence[int]) -> Dict[int, float]:
    sieve = bytearray([1]) * (bound + 1)
    sieve[0:2] = b"\x00\x00"
    for i in range(2, int(bound ** 0.5) + 1):
        if sieve[i]:
            sieve[i * i:: i] = bytearray(len(sieve[i * i:: i]))
    data = [(p, factor_degrees([c % p for c in coeffs], p))
            for p in range(bound + 1) if sieve[p] and p not in ramified]
    return {m: mutual_information([(t, p % m) for p, t in data]) for m in moduli}


